  function injectSpaceTraffic() {
    if (document.getElementById(TRAFFIC_ID)) return;
    const traffic = document.createElement("div");
    traffic.id = TRAFFIC_ID;
    traffic.className = "cd-v45-traffic";
    traffic.setAttribute("aria-hidden", "true");
    traffic.innerHTML = [
      '<span class="cd-v45-meteor"><i class="cd-v47-meteor-tail"></i><i class="cd-v47-meteor-head"></i></span>',
      '<span class="cd-v45-ship ship-earth"><i class="cd-v45-ship-hull"></i><i class="cd-v45-ship-core"></i><i class="cd-v45-ship-light"></i><i class="cd-v45-ship-cloak"></i></span>',
      '<span class="cd-v45-ship ship-close"><i class="cd-v45-ship-ring"></i><i class="cd-v45-ship-wing wing-a"></i><i class="cd-v45-ship-wing wing-b"></i><i class="cd-v45-ship-hull"></i><i class="cd-v45-ship-core"></i><i class="cd-v45-ship-light"></i></span>'
    ].join("");
    document.body.appendChild(traffic);
    scheduleMeteor(8000);
  }

  function triggerMeteor() {
    if (!state.prefs.traffic || document.visibilityState !== "visible") return;
    const meteor = document.querySelector(`#${TRAFFIC_ID} .cd-v45-meteor`);
    if (!meteor) return;
    const fromLeft = Math.random() < .5;
    const startX = fromLeft ? -8 : 108;
    const startY = 8 + Math.random() * 30;
    const endX = fromLeft ? 68 + Math.random() * 34 : 24 - Math.random() * 34;
    const endY = 52 + Math.random() * 38;
    const dxPx = ((endX - startX) / 100) * innerWidth;
    const dyPx = ((endY - startY) / 100) * innerHeight;
    const angle = Math.atan2(dyPx, dxPx) * 180 / Math.PI;
    const length = 105 + Math.random() * 90;
    const duration = 2.3 + Math.random() * 1.1;
    meteor.style.setProperty("--meteor-start-x", `${startX.toFixed(1)}vw`);
    meteor.style.setProperty("--meteor-start-y", `${startY.toFixed(1)}vh`);
    meteor.style.setProperty("--meteor-end-x", `${endX.toFixed(1)}vw`);
    meteor.style.setProperty("--meteor-end-y", `${endY.toFixed(1)}vh`);
    meteor.style.setProperty("--meteor-angle", `${angle.toFixed(1)}deg`);
    meteor.style.setProperty("--meteor-length", `${length.toFixed(0)}px`);
    meteor.style.setProperty("--meteor-duration", `${duration.toFixed(2)}s`);
    meteor.classList.remove("cd-v47-meteor-active");
    void meteor.offsetWidth;
    meteor.classList.add("cd-v47-meteor-active");
    clearTimeout(state.meteorClearTimer);
    state.meteorClearTimer = window.setTimeout(() => {
      meteor.classList.remove("cd-v47-meteor-active");
    }, Math.round(duration * 1000) + 260);
  }

  function scheduleMeteor(delay = 60000) {
    clearTimeout(state.meteorTimer);
    state.meteorTimer = window.setTimeout(() => {
      triggerMeteor();
      scheduleMeteor(60000);
    }, delay);
  }

  function clearMeteorTimers() {
    clearTimeout(state.meteorTimer);
    clearTimeout(state.meteorClearTimer);
    state.meteorTimer = 0;
    state.meteorClearTimer = 0;
    document.querySelector(`#${TRAFFIC_ID} .cd-v45-meteor`)?.classList.remove("cd-v47-meteor-active");
  }

